import Foundation
import AVFoundation
import CWhisper

// Диагностика цепочки распознавания VoiceCapture.
// 1) пишет N секунд с микрофона тем же путём (AVAudioEngine -> 16kHz mono float)
// 2) считает RMS/пики (есть ли вообще звук)
// 3) гоняет через whisper.cpp с текущей моделью и печатает текст

let targetSampleRate: Double = 16000

final class DiagRecorder {
    let engine = AVAudioEngine()
    var converter: AVAudioConverter?
    var targetFormat: AVAudioFormat!
    var samples: [Float] = []
    let q = DispatchQueue(label: "diag.samples")

    init() {
        targetFormat = AVAudioFormat(commonFormat: .pcmFormatFloat32,
                                     sampleRate: targetSampleRate,
                                     channels: 1, interleaved: false)
    }

    func record(seconds: Double) -> [Float] {
        let input = engine.inputNode
        let inputFormat = input.inputFormat(forBus: 0)
        print("[Diag] Вход микрофона: \(inputFormat.sampleRate) Hz, каналов \(inputFormat.channelCount)")
        guard inputFormat.sampleRate > 0 else {
            print("[Diag] ОШИБКА: нет микрофона / нулевой формат")
            return []
        }
        converter = AVAudioConverter(from: inputFormat, to: targetFormat)
        input.installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] buf, _ in
            self?.process(buf, inputFormat)
        }
        do {
            engine.prepare()
            try engine.start()
        } catch {
            print("[Diag] ОШИБКА engine.start: \(error)")
            return []
        }
        print("[Diag] Говорите \(seconds) сек...")
        Thread.sleep(forTimeInterval: seconds)
        input.removeTap(onBus: 0)
        engine.stop()
        return q.sync { samples }
    }

    func process(_ buffer: AVAudioPCMBuffer, _ inputFormat: AVAudioFormat) {
        guard let converter = converter else { return }
        let ratio = targetFormat.sampleRate / inputFormat.sampleRate
        let cap = AVAudioFrameCount(Double(buffer.frameLength) * ratio + 1024)
        guard let out = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: cap) else { return }
        var consumed = false
        var err: NSError?
        let status = converter.convert(to: out, error: &err) { _, st in
            if consumed { st.pointee = .noDataNow; return nil }
            consumed = true; st.pointee = .haveData; return buffer
        }
        if status == .error { print("[Diag] convert error: \(String(describing: err))"); return }
        guard let ch = out.floatChannelData else { return }
        let n = Int(out.frameLength)
        guard n > 0 else { return }
        let chunk = Array(UnsafeBufferPointer(start: ch[0], count: n))
        q.sync { samples.append(contentsOf: chunk) }
    }
}

func transcribe(_ samples: [Float], modelPath: String, language: String) -> String? {
    guard FileManager.default.fileExists(atPath: modelPath) else {
        print("[Diag] ОШИБКА: модель не найдена: \(modelPath)")
        return nil
    }
    var cparams = whisper_context_default_params()
    cparams.use_gpu = false
    let ctxOpt = modelPath.withCString { whisper_init_from_file_with_params($0, cparams) }
    guard let ctx = ctxOpt else { print("[Diag] ОШИБКА: модель не загрузилась"); return nil }
    defer { whisper_free(ctx) }
    print("[Diag] Модель загружена OK")

    var params = whisper_full_default_params(WHISPER_SAMPLING_GREEDY)
    params.print_realtime = false
    params.print_progress = false
    params.print_timestamps = false
    params.print_special = false
    params.translate = false
    params.no_timestamps = true
    params.suppress_blank = true
    params.n_threads = Int32(max(1, ProcessInfo.processInfo.activeProcessorCount - 1))

    let result: Int32
    if language == "auto" || language.isEmpty {
        params.language = nil
        params.detect_language = true
        result = samples.withUnsafeBufferPointer { whisper_full(ctx, params, $0.baseAddress, Int32($0.count)) }
    } else {
        result = language.withCString { lp -> Int32 in
            params.language = lp
            return samples.withUnsafeBufferPointer { whisper_full(ctx, params, $0.baseAddress, Int32($0.count)) }
        }
    }
    guard result == 0 else { print("[Diag] ОШИБКА: whisper_full вернул \(result)"); return nil }

    var text = ""
    let segs = whisper_full_n_segments(ctx)
    print("[Diag] Сегментов: \(segs)")
    for i in 0..<segs {
        if let c = whisper_full_get_segment_text(ctx, i) { text += String(cString: c) }
    }
    return text.trimmingCharacters(in: .whitespacesAndNewlines)
}

// --- main ---
let modelsDir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
    .appendingPathComponent("VoiceCapture/Models", isDirectory: true)
let modelPath = modelsDir.appendingPathComponent("ggml-large-v3.bin").path
let language = "ru"
let seconds = 4.0

print("[Diag] Модель: \(modelPath)")
print("[Diag] Запрос доступа к микрофону...")

let sem = DispatchSemaphore(value: 0)
var granted = false
switch AVCaptureDevice.authorizationStatus(for: .audio) {
case .authorized:
    granted = true; sem.signal()
case .notDetermined:
    AVCaptureDevice.requestAccess(for: .audio) { g in granted = g; sem.signal() }
default:
    granted = false; sem.signal()
}
sem.wait()
print("[Diag] Доступ к микрофону: \(granted)")
guard granted else {
    print("[Diag] Нет доступа к микрофону — выходим")
    exit(1)
}

let rec = DiagRecorder()
let samples = rec.record(seconds: seconds)
print("[Diag] Записано сэмплов: \(samples.count) (~\(String(format: "%.1f", Double(samples.count) / targetSampleRate)) c)")

if !samples.isEmpty {
    let rms = sqrt(samples.reduce(0) { $0 + $1 * $1 } / Float(samples.count))
    let peak = samples.map { abs($0) }.max() ?? 0
    print("[Diag] RMS=\(rms)  Peak=\(peak)")
    if peak < 0.005 {
        print("[Diag] ВНИМАНИЕ: сигнал почти тишина (peak < 0.005). Микрофон не пишет звук!")
    }
}

if let text = transcribe(samples, modelPath: modelPath, language: language) {
    print("==================================================")
    print("[Diag] РЕЗУЛЬТАТ: '\(text)'")
    print("==================================================")
} else {
    print("[Diag] Распознавание не дало результата")
}
